    'the client directory is a convention of each client; use --dir if it is wrong') printf '%s' '客戶端目錄是各家自己的約定；不對就用 --dir 指定' ;;
    'installed the skill into') printf '%s' '已把 skill 裝進' ;;
    'unknown AI client') printf '%s' '未知的 AI 客戶端' ;;
    'no AI client directory found; use --dir') printf '%s' '沒找到 AI 客戶端目錄；用 --dir 指定' ;;
    'removed the skill from') printf '%s' '已從下列目錄移除 skill' ;;
    'this copy has no skill package') printf '%s' '這份副本裡沒有 skill 包' ;;
    'only one action is allowed') printf '%s' '只允許一個動作' ;;
    'only one client is allowed') printf '%s' '只允許一個客戶端' ;;
    'try a writable prefix') printf '%s' '換一個可寫的前綴' ;;
    'recovering the installed copy after an interrupted swap') printf '%s' '正在從被打斷的切換中恢復已安裝的副本' ;;
    'installing') printf '%s' '正在安裝' ;;
    'failed to write the install manifest') printf '%s' '寫入安裝清單失敗' ;;
    'failed to create symlink') printf '%s' '建立符號連結失敗' ;;
    'no install manifest under') printf '%s' '這裡沒有安裝清單：' ;;
    'nothing was removed, delete that directory by hand if you are sure') printf '%s' '沒有刪除任何東西；確認無誤請手動刪除該目錄' ;;
    'removing') printf '%s' '正在刪除：' ;;
    'skipped a path outside the install directory') printf '%s' '跳過了安裝目錄之外的路徑：' ;;
    'failed to remove') printf '%s' '刪除失敗：' ;;
    'leftover files were kept') printf '%s' '保留了未清理的檔案：' ;;
    'left the symlink alone, it points elsewhere') printf '%s' '未動該符號連結，它指向別處：' ;;
    'left the file alone, it is not a symlink') printf '%s' '未動該檔案，它不是符號連結：' ;;
    'removed') printf '%s' '已刪除：' ;;
    'files') printf '%s' '個檔案' ;;
    'no such file') printf '%s' '檔案不存在：' ;;
    'checking for a newer version') printf '%s' '正在檢查新版本' ;;
    'cannot read the latest version from the release API') printf '%s' '無法從 release API 讀出最新版本' ;;
    'already up to date') printf '%s' '已是最新版本：' ;;
    'current version') printf '%s' '目前版本：' ;;
    'latest version') printf '%s' '最新版本：' ;;
    'no checksum for this release') printf '%s' '該版本沒有校驗和：' ;;
    'no checksum provided, skipping verification') printf '%s' '沒有提供校驗和，跳過校驗：' ;;
    'cannot extract archive') printf '%s' '無法解包：' ;;
    'not a shellkit release') printf '%s' '這不是 shellkit 的發佈包：' ;;
    'cannot read the version of') printf '%s' '無法讀取版本號：' ;;
    'shellkit is not installed under') printf '%s' 'shellkit 沒有裝在：' ;;
    'run install-self first, or point --prefix at the right place') printf '%s' '先跑 install-self，或把 --prefix 指到正確位置' ;;
    'updating') printf '%s' '正在更新：' ;;
    'update failed') printf '%s' '更新失敗：' ;;
    'running') printf '%s' '正在執行' ;;
    'target') printf '%s' '目標' ;;
    'force flag is set') printf '%s' '已開啟強制模式' ;;
    'finished') printf '%s' '完成' ;;
    *) return 1 ;;
  esac
}
